export type PromotionCodeInput = { "code": string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string | globalThis.Date; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "max_uses"?: string; "merchant_id"?: string; "metadata"?: Record<string, string>; /** The promotion this code belongs to. Present only when the list request asked for expand=promotion. */ "promotion"?: { "application_method": PromotionApplicationMethodInput; /** Read-only rollup of this promotion's codes. Present only on code-gated promotions; automatic promotions omit it. */ "codes_summary"?: { /** Number of codes that can still be redeemed right now. Zero means the promotion reads as no_active_codes. Format: int32. */ "active_count": number; /** Most recently created redeemable code. Omitted when active_count is zero. */ "newest_active_code"?: string; /** Number of codes on the promotion, excluding deleted codes. Format: int32. */ "total_count": number; }; "combines_with"?: PromotionCombinesWithInput; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string | globalThis.Date; "description"?: string; "discount_class": "order" | "line_item" | "service_charge"; /** Buyer-facing promotion name shown in checkout and order discount surfaces. */ "display_name": string; /** A rule group is exactly one of three forms, never a blend: an array of rules for a simple list (an implicit AND), an object with only all for nested AND, or an object with only any for OR. The all and any arrays contain rules or nested rule groups. There is no rules key. Sending a rules key, an unexpected key, or both all and any is rejected with INVALID_RULE_GROUP. */ "eligibility_rules"?: ((Array<PromotionRuleInput>) | ({ "all": Array<(({ /** Field the rule tests. The attribute fixes the value type and the operators that are legal for it: money attributes accept comparison operators but not eq or in, booleans accept eq only, and so on. The full attribute/type/operator matrix is machine-readable in x-flint-rule-attributes on this schema. metadata.<key> reads a string from the customer's metadata and accepts the string operators. A disallowed operator is rejected at create time with INVALID_OPERATOR, whose message names the operators allowed for the attribute. */ "attribute": string; "currency_options"?: Record<string, MoneyValueInput>; "operator": "eq" | "ne" | "gt" | "gte" | "lt" | "lte" | "in" | "contains" | "is_defined"; "values"?: Array<PromotionRuleValueInput>; }) | (PromotionRuleGroupInput))>; }) | ({ "any": Array<(({ /** Field the rule tests. The attribute fixes the value type and the operators that are legal for it: money attributes accept comparison operators but not eq or in, booleans accept eq only, and so on. The full attribute/type/operator matrix is machine-readable in x-flint-rule-attributes on this schema. metadata.<key> reads a string from the customer's metadata and accepts the string operators. A disallowed operator is rejected at create time with INVALID_OPERATOR, whose message names the operators allowed for the attribute. */ "attribute": string; "currency_options"?: Record<string, MoneyValueInput>; "operator": "eq" | "ne" | "gt" | "gte" | "lt" | "lte" | "in" | "contains" | "is_defined"; "values"?: Array<PromotionRuleValueInput>; }) | (PromotionRuleGroupInput))>; })); "exclusivity"?: PromotionExclusivityInput; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "max_uses"?: string; "merchant_id"?: string; "metadata"?: Record<string, string>; /** Internal promotion name for dashboards, searching, and reporting. */ "name": string; "promotion_id": string; "redemption_type": "automatic" | "code"; "schedule"?: PromotionScheduleInput; "stacking_mode": "continue" | "stop_after"; /** Read-only, computed from the schedule, usage, and codes: active, inactive, expired, not_yet_started, exhausted, no_active_codes, or archived. Only active and inactive can be set via PATCH. */ "status": "active" | "inactive" | "expired" | "not_yet_started" | "exhausted" | "no_active_codes" | "archived"; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string | globalThis.Date; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "uses_count": string; }; "promotion_code_id": string; "promotion_id": string; /** Read-only, computed from stored active or inactive state, expires_at, and max_uses: active, inactive, expired, or exhausted. Only active and inactive can be set via PATCH. */ "status": "active" | "inactive" | "expired" | "exhausted"; "timezone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string | globalThis.Date; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "uses_count": string; };
